@page "/recipe/{Id:int}"
@using RecipeHub.Services
@using RecipeHub.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <span class="badge">@recipe.Category</span>

    <section class="recipe-section">
        <h2>🥘 Ingredients</h2>
        <ul>
            @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <li>@ingredient</li>
            }
        </ul>
    </section>

    <section class="recipe-section">
        <h2>👨‍🍳 Steps</h2>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <p>@step</p>
        }
    </section>

    <section class="recipe-section">
        <h2>⭐ Rating</h2>
        <StarRating RecipeId="@recipe.Id"
                    AverageRating="@recipe.AverageRating"
                    TotalRatings="@recipe.Ratings.Count"
                    OnRate="HandleRating" />
    </section>
}

<p><a href="/">← Back to home</a></p>

@code {
    [Parameter] public int Id { get; set; }
    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }

    private void HandleRating(int stars)
    {
        RecipeService.AddRating(Id, stars);
        recipe = RecipeService.GetRecipeById(Id);
    }
}

