@page "/recipes/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in recipes)
        {
            <a href="recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <p class="recipe-meta">
                    @if (recipe.Ratings.Count > 0)
                    {
                        <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.Ratings.Count ratings)</span>
                    }
                    else
                    {
                        <span>No ratings yet</span>
                    }
                </p>
            </a>
        }
    </div>
}

<p><a href="/">← Back to categories</a></p>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    private List<RecipeHub.Models.Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

